// دفاعي — عمره ما يرمي. يطلّع object موحّد من payload الـ Evolution (messages.upsert).
try {
  const root = $json.body || $json;
  const event = String(root.event || '').toLowerCase().replace(/_/g, '.');
  const data = root.data || {};
  const key = data.key || {};
  const msg = data.message || {};
  const fromMe = key.fromMe === true;
  const remoteJidFull = String(key.remoteJid || '');
  const isGroup = remoteJidFull.endsWith('@g.us');
  const phone = remoteJidFull.split('@')[0].replace(/\D/g, '');
  const waMessageId = String(key.id || '');
  let body = '';
  if (typeof msg.conversation === 'string') body = msg.conversation;
  else if (msg.extendedTextMessage && typeof msg.extendedTextMessage.text === 'string') body = msg.extendedTextMessage.text;
  else if (msg.imageMessage && typeof msg.imageMessage.caption === 'string') body = msg.imageMessage.caption;
  else if (msg.documentMessage && typeof msg.documentMessage.caption === 'string') body = msg.documentMessage.caption;
  body = String(body || '').trim();
  const hasImage = !!msg.imageMessage || !!msg.documentMessage;
  const hasAudio = !!msg.audioMessage || !!msg.pttMessage;
  const hasVideo = !!msg.videoMessage;
  // السكرين/الميديا بتفضل مرئية للفريق في شات الدعم نفسه — بنسجل ماركر بس
  const mediaUrl = hasImage ? '[صورة/ملف مرفق في محادثة واتساب الدعم]' : '';
  // الصوتيات/الفيديو مايتجاهلوش بصمت — الـ prompt (قاعدة 13) بيرد عليهم بطلب نص
  if (!body) {
    if (hasAudio) body = '[رسالة صوتية من العميل]';
    else if (hasVideo) body = '[فيديو من العميل]';
    else if (hasImage) body = '[العميل بعت صورة من غير نص]';
  }
  const pushName = String(data.pushName || '').trim();
  const isMessage = !fromMe && !isGroup && event === 'messages.upsert' && !!waMessageId && !!phone && !!body;
  return { json: { isMessage, phone, remoteJidFull, waMessageId, body, mediaUrl, pushName, hasAudio, hasImage } };
} catch (e) {
  return { json: { isMessage: false, phone: '', remoteJidFull: '', waMessageId: '', body: '', mediaUrl: '', pushName: '' } };
}

// نمط rs-aios Hybrid Memory: prompt من الـ DB + بروفايل العميل محقون في الآخر
const prompt = $('Fetch Active Prompt').first().json.prompt_text || '';
if (!prompt || prompt.length < 2000) throw new Error('Active prompt مفقود/قصير — راجع omar.agent_prompts');
const c = $('Upsert Contact').first().json || {};
const hrs = Number(c.hours_since_last_seen);
const ageText = hrs < 0 ? 'أول مرة يتواصل' : hrs < 1 ? 'أقل من ساعة' : hrs < 24 ? Math.round(hrs) + ' ساعة' : Math.round(hrs / 24) + ' يوم';
const interests = Array.isArray(c.course_interest) ? c.course_interest.join(', ') : '';
const nowCairo = new Date().toLocaleString('sv-SE', { timeZone: 'Africa/Cairo' }).slice(0, 16);
let profile = `\n\n---\n[التاريخ والوقت دلوقتي (القاهرة): ${nowCairo}]\n[سياق العميل الحالي — من قاعدة البيانات، مش من العميل]\nالاسم: ${c.name || 'غير معروف'} · الإيميل: ${c.email || 'غير معروف'} · الحالة: ${c.lead_status || 'new'} · اهتمامات سابقة: ${interests || 'مفيش'} · الدولة: ${c.country || 'غير معروفة'} · إجمالي رسايله: ${c.total_messages || 1} · آخر تواصل: ${ageText}`;
if (hrs > 48) profile += `\n⚠️ العميل راجع بعد فترة طويلة — السياق القديم ممكن يكون اتغيّر. اتعامل معاه كبداية محادثة جديدة وراجع أي تفاصيل قديمة قبل ما تبني عليها.`;
profile += `\n(استخدم السياق ده في ردّك بس متقروش حرفياً للعميل.)`;
return { json: { systemPrompt: prompt + profile, batch: $json.batch || $('Resolve Message').item.json.body } };

// نمط rs-aios Clean AI Response + فخ الـ maxIterations (n8n بيرجّع النص ده حرفياً للعميل!)
let out = String($json.output ?? '').trim();
let agentDegraded = false;
if (!out || /agent stopped due to max iterations/i.test(out)) {
  agentDegraded = true;
  out = 'معلش الرد اتأخر عليا 🙏 ممكن توضحلي سؤالك بشكل أبسط؟ ولو مستعجل، حد من الفريق بيتابع الشات ده في ساعات العمل.';
}
out = out.replace(/```[a-z]*\r?\n?/gi, '').trim();
// شيل أي "إيصالات" مزيفة شكلها سيستم — سطر كامل بين أقواس مربعة + فواصل --- في الآخر
out = out.split('\n').filter(l => !/^\s*\[[^\]\n]{2,60}\]\s*$/.test(l.trim())).join('\n');
out = out.replace(/(\n\s*-{3,}\s*)+$/g, '').trim();
if (out.length > 1900) out = out.slice(0, 1897) + '…';

// 🛡️ حارس التصعيد الحتمي: وعد بالتصعيد من غير نداء الأداة = mismatch → الفرع الجانبي بيطلق W3b بنفسه
let escalateRan = false;
try { escalateRan = ($('escalate').all() || []).length > 0; } catch (e) {}
const doneClaim = /(وصّ?لت|بلّغت|تم (التصعيد|تسجيل الحالة|إبلاغ|الإبلاغ|رفع الحالة))/.test(out);
const futureClaim = /(هوصّل|هأوصّل|أوصّل|هبلّغ|هرفع|بعد ما|أول ما)/.test(out);
const escalationCtx = /(للفريق|لأحمد|التصعيد)/.test(out);
const promised = doneClaim && escalationCtx && !futureClaim;
const promiseMismatch = promised && !escalateRan && !agentDegraded;
let guardType = 'access', guardSummary = '';
if (promiseMismatch) {
  const m = out.match(/(payment_intl|site_access|for_ahmed|certificate|access|payment|refund|angry)/);
  if (m) guardType = m[1];
  let batch = '';
  try { batch = String($('Build Prompt & Profile').item.json.batch || ''); } catch (e) {}
  guardSummary = '⚠️ حارس آلي (promise-mismatch): الوكيل وعد العميل بالتصعيد من غير ما ينده أداة escalate — التصعيد ده اتولّد أوتوماتيك من الحارس. رسالة العميل: «' + batch.slice(0, 400) + '» · رد الوكيل: «' + out.slice(0, 300) + '»';
}
return { json: { reply: out, agentDegraded, promiseMismatch, guardType, guardSummary } };

