// البوت على رقم الدعم نفسه اللي أحمد بيتابعه — فالإحالة للفريق حقيقية مش وعد فاضي
return { json: { reply: 'معلش، السيستم واقف معايا شوية 🙏 سيبلي رسالتك هنا وحد من الفريق هيرد عليك في ساعات العمل (السبت للخميس، 10ص-6م)', agentDegraded: true } };

const j = $input.first().json;
const b64 = (j.data && j.data.base64) || j.base64 || j.mediaBase64 || '';
if (!b64) throw new Error('no audio base64 from Evolution');
const bin = await this.helpers.prepareBinaryData(Buffer.from(b64, 'base64'), 'audio.ogg', 'audio/ogg');
return [{ json: j, binary: { data: bin } }];

