let body = String(norm.body || '');
function gtext(j){
  if (!j) return '';
  try { if (j.content && j.content.parts && j.content.parts[0] && j.content.parts[0].text) return String(j.content.parts[0].text).trim(); } catch(e){}
  if (typeof j.text === 'string') return j.text.trim();
  if (typeof j.response === 'string') return j.response.trim();
  if (typeof j.output === 'string') return j.output.trim();
  if (typeof j.content === 'string') return j.content.trim();
  return '';
}
if (norm.hasAudio) {
  let t=''; try { t = gtext($('Analyze Audio').first().json); } catch(e){}
  body = t ? ('العميل بعت رسالة صوتية، وده تفريغ كلامه:\n' + t) : 'العميل بعت رسالة صوتية بس مش قادر أفرّغها — اطلب منه بلطف يكتبلك سؤاله.';
} else if (norm.hasImage) {
  let t=''; try { t = gtext($('Analyze Image').first().json); } catch(e){}
  body = t ? ('العميل بعت صورة، وده اللي فيها (قراءة آلية للصورة حاول تساعده بقدر الامكان من المعرفة اللي عندك):\n' + t) : 'العميل بعت صورة بس مش قادر أقراها بوضوح — اطلب منه يوضّح أو يكتب اللي محتاجه.';
}
return [{ json: Object.assign({}, norm, { body: body }) }];

